<script lang="ts">
  import { onMount } from "svelte";
  import { Archive, ArrowLeft, Check, GitBranch, Link2, Pause, Pencil, Play, RefreshCw, RotateCcw, ShieldCheck, Wrench } from "@lucide/svelte";
  import { locale, t } from "./i18n";
  import ApprovalPanel from "./ApprovalPanel.svelte";
  import UserInputPanel from "./UserInputPanel.svelte";
  import { archiveBoardCard, attachBoardSession, awaitingBoardApproval, boardAction, boardAutomationAction, boardAutomationReasonKey, boardCollaborationWaitingKey, boardDecisionSessions, boardProviderExecution, boardWaitingCollaborationSessions, cardNeedsAttention, getBoardCard, listBoardEvents, normalizeBoardCard, reopenBoardCard, updateBoardCard, type BoardApi, type CollaborationBoardAttachCandidate, type CollaborationBoardCard, type CollaborationBoardDraft, type CollaborationBoardEvent, type CollaborationBoardExecutionConfig, type CollaborationBoardRole } from "./collaboration-board";
  import { providerDisplayName } from "./provider-display";
  import { automationLevelLabel, automationLevelOf } from "./automation-level";
  import { modelLabel } from "./session-ui";
  export let api:BoardApi;
  export let card:CollaborationBoardCard;
  export let executionConfig:CollaborationBoardExecutionConfig;
  export let sessionCandidates:CollaborationBoardAttachCandidate[]=[];
  export let workspaceName="";
  export let onback:()=>void=()=>{};
  export let onedit:(card:CollaborationBoardCard)=>void=()=>{};
  export let onchanged:(card:CollaborationBoardCard)=>void=()=>{};
  export let onaction:()=>void|Promise<void>=()=>{};
  export let onopensession:(kind:"task"|"collaboration",id:string)=>void=()=>{};
  const SESSION_LIMIT=5,EVENT_LIMIT=8;
  let events:CollaborationBoardEvent[]=[];let loading=true;let busy="";let notice="";let attachSelection="";let showAttach=false;let stopAfter:"work"|"review"|null=card.automation.stopAfter;let showAllSessions=false;let showAllEvents=false;
  const formatted=(value?:string|null)=>value?new Intl.DateTimeFormat($locale,{dateStyle:"medium",timeStyle:"short"}).format(new Date(value)):$t("common.unknown");
  const payload=(event:CollaborationBoardEvent)=>event.payload??(()=>{try{return JSON.parse(event.payloadJson??"{}")}catch{return {}}})();
  const canReview=()=>Boolean(card.roles.implementer&&card.roles.reviewer&&card.roles.implementer.provider!==card.roles.reviewer.provider);
  const automationStartBlock=()=>!card.workspaceId?"collaborationBoard.automation.startNeedsWorkspace":!canReview()?"collaborationBoard.reviewRolesRequired":"";
  $: decisionSessions=boardDecisionSessions(card);
  $: waitingCollaborations=boardWaitingCollaborationSessions(card);
  $: reasonKey=boardAutomationReasonKey(card.automation.pauseReason);
  const roleSummary=(role:CollaborationBoardRole)=>{const model=boardProviderExecution(executionConfig,role.provider)?.models.find(item=>item.id===role.model),automation=role.automationLevel??automationLevelOf(role.permissionProfile,null);return`${model?modelLabel(model):role.model??$t("collaborationBoard.defaultModel")} · ${automationLevelLabel(automation)}`;};
  async function load(){loading=true;try{events=await listBoardEvents(api,card.id)}catch(error){notice=error instanceof Error?error.message:String(error)}finally{loading=false}}
  async function refresh(){if(busy)return;try{const next=await getBoardCard(api,card.id);if(next.revision!==card.revision||next.lastActivityAt!==card.lastActivityAt){card=next;onchanged(card);events=await listBoardEvents(api,card.id)}}catch{}}
  async function action(name:"start-work"|"request-review"|"start-revision"|"resume"){busy=name;notice="";try{const full=(name==="start-work"||name==="start-revision")&&card.roles.implementer?.automationLevel==="full",result=await boardAction(api,card,name,full&&executionConfig.fullAccessAcknowledged?{dangerConfirmation:true,fullAccessAcknowledged:true,acknowledgementVersion:1}:{});if(result?.card){card=result.card;onchanged(card)}try{await onaction()}catch{}await load();notice=$t("collaborationBoard.actionStarted")}catch(error){notice=error instanceof Error?error.message:String(error)}finally{busy=""}}
  async function setStatus(status:CollaborationBoardDraft["boardStatus"]){busy=status;try{card=await updateBoardCard(api,card,{boardStatus:status});onchanged(card)}catch(error){notice=error instanceof Error?error.message:String(error)}finally{busy=""}}
  async function archive(){busy="archive";try{card=await archiveBoardCard(api,card);onchanged(card);onback()}catch(error){notice=error instanceof Error?error.message:String(error)}finally{busy=""}}
  async function reopen(){busy="reopen";try{card=await reopenBoardCard(api,card);onchanged(card)}catch(error){notice=error instanceof Error?error.message:String(error)}finally{busy=""}}
  async function attach(){const [kind,...parts]=attachSelection.split(":"),id=parts.join(":");if(!id)return;busy="attach";try{card=await attachBoardSession(api,card,kind==="task"?{taskId:id}:{collaborationSessionId:id});attachSelection="";showAttach=false;onchanged(card);await load()}catch(error){notice=error instanceof Error?error.message:String(error)}finally{busy=""}}
  async function automate(action:"start"|"pause"|"resume"|"decision",body:Record<string,unknown>={}){busy=`automation-${action}`;notice="";try{const full=card.roles.implementer?.automationLevel==="full",result=await boardAutomationAction(api,card,action,{...body,...(action==="start"?{stopAfter,...(full&&executionConfig.fullAccessAcknowledged?{fullAccessAcknowledged:true,acknowledgementVersion:1}:{})}:{})});card=normalizeBoardCard(result.card);onchanged(card);await load()}catch(error){notice=error instanceof Error?error.message:String(error)}finally{busy=""}}
  onMount(()=>{const timer=setInterval(()=>void refresh(),5000);return()=>clearInterval(timer)});
  $: card.id,(showAllSessions=false,showAllEvents=false,load());
  $: hiddenSessions=Math.max(0,card.sessions.length-SESSION_LIMIT);
  $: visibleSessions=showAllSessions||!hiddenSessions?card.sessions:card.sessions.slice(0,SESSION_LIMIT);
  $: hiddenEvents=Math.max(0,events.length-EVENT_LIMIT);
  $: visibleEvents=showAllEvents||!hiddenEvents?events:events.slice(events.length-EVENT_LIMIT);
</script>

<section class="board-detail">
  <header class="detail-header"><button type="button" class="back" onclick={onback}><ArrowLeft size={18}/>{$t("common.back")}</button><div class="header-actions"><button type="button" onclick={()=>onedit(card)}><Pencil size={16}/>{$t("common.edit")}</button>{#if card.archivedAt}<button type="button" onclick={reopen} disabled={!!busy}><RotateCcw size={16}/>{$t("collaborationBoard.reopen")}</button>{:else}<button type="button" onclick={archive} disabled={!!busy}><Archive size={16}/>{$t("collaborationBoard.archive")}</button>{/if}</div></header>
  <div class="hero"><div><span class="kicker">{$t("collaborationBoard.kicker")}</span><h1>{card.title}</h1><p>{card.description||$t("collaborationBoard.noDescription")}</p></div><div class="hero-state"><span class:attention={cardNeedsAttention(card)}>{$t(`collaborationBoard.status.${card.boardStatus}`)}</span><small>{$t(`collaborationBoard.priority.${card.priority}`)}</small></div></div>
  <div class="facts"><span><strong>{$t("workspace.label")}</strong>{workspaceName||$t("workspace.noWorkspace")}</span><span><strong>{$t("collaborationBoard.field.branch")}</strong><i><GitBranch size={13}/>{card.targetBranch||"—"}</i></span><span><strong>{$t("collaborationBoard.lastActivity")}</strong>{formatted(card.lastActivityAt)}</span></div>
  <div class="actions"><button onclick={()=>action("start-work")} disabled={!!busy}><Play size={16}/>{$t("collaborationBoard.startWork")}</button><button onclick={()=>action("request-review")} disabled={!!busy||!canReview()} title={!canReview()?$t("collaborationBoard.reviewRolesRequired"):undefined}><ShieldCheck size={16}/>{$t("collaborationBoard.requestReview")}</button><button onclick={()=>action("start-revision")} disabled={!!busy}><Wrench size={16}/>{$t("collaborationBoard.startRevision")}</button><button onclick={()=>action("resume")} disabled={!!busy}><RefreshCw size={16}/>{$t("task.resume")}</button>{#if card.boardStatus!=="completed"}<button class="complete" onclick={()=>setStatus("completed")} disabled={!!busy}><Check size={16}/>{$t("collaborationBoard.complete")}</button>{:else}<button onclick={()=>setStatus("in_progress")} disabled={!!busy}><RotateCcw size={16}/>{$t("collaborationBoard.reopen")}</button>{/if}</div>
  <section class="automation-bar" aria-label={$t("collaborationBoard.automation.title")}><div><strong>{$t("collaborationBoard.automation.title")}</strong><small>{$t(`collaborationBoard.automation.state.${card.automation.state}`)}{#if card.automation.stage} · {$t(`collaborationBoard.automation.stage.${card.automation.stage}`)}{/if}{#if card.automation.round} · {$t("collaborationBoard.automation.round",{count:card.automation.round})}{/if}</small>{#if reasonKey}<em>{$t(`collaborationBoard.automation.reason.${reasonKey}`)}</em>{:else if card.automation.pauseReason}<em>{card.automation.pauseReason}</em>{/if}</div>{#if card.automation.mode!=="auto"}<label><span>{$t("collaborationBoard.automation.stopAfter")}</span><select bind:value={stopAfter}><option value={null}>{$t("collaborationBoard.automation.stop.none")}</option><option value="work">{$t("collaborationBoard.automation.stop.work")}</option><option value="review">{$t("collaborationBoard.automation.stop.review")}</option></select></label><button onclick={()=>automate("start")} disabled={!!busy||!!automationStartBlock()} title={automationStartBlock()?$t(automationStartBlock()):undefined}><Play size={16}/>{$t("collaborationBoard.automation.start")}</button>{:else if awaitingBoardApproval(card)}<button class="complete" onclick={()=>automate("decision",{decision:"approve"})} disabled={!!busy}><Check size={16}/>{$t("collaborationBoard.automation.approve")}</button><button onclick={()=>automate("decision",{decision:"revise"})} disabled={!!busy}><Wrench size={16}/>{$t("collaborationBoard.automation.revise")}</button>{:else if card.automation.state==="running"||card.automation.state==="stopping"}<button onclick={()=>automate("pause")} disabled={!!busy||card.automation.state==="stopping"}><Pause size={16}/>{$t(card.automation.state==="stopping"?"collaborationBoard.automation.stopping":"collaborationBoard.automation.pause")}</button>{:else if card.automation.state==="paused"||card.automation.state==="blocked"}<button onclick={()=>automate("resume")} disabled={!!busy}><RefreshCw size={16}/>{$t(card.automation.state==="blocked"?"collaborationBoard.automation.retry":"collaborationBoard.automation.resume")}</button>{/if}</section>
  {#if automationStartBlock()&&card.automation.mode!=="auto"}<p class="notice" role="status">{$t(automationStartBlock())}</p>{/if}
  {#each decisionSessions as session}{@const provider=session.provider}
    {#if provider&&session.status==="waiting-approval"}<ApprovalPanel api={api as any} task={{id:session.id,provider,status:session.status,executionHostId:session.executionHostId,title:session.title}}/>{/if}
    {#if provider&&(session.status==="waiting-user"||session.status==="waiting")}<UserInputPanel api={api as any} task={{id:session.id,provider,title:session.title,status:session.status}}/>{/if}
  {/each}
  {#each waitingCollaborations as session}
    <p class="notice collaboration-wait" role="status">{$t(boardCollaborationWaitingKey(session.status))}<button type="button" onclick={()=>onopensession(session.kind,session.id)}>{$t("collaborationBoard.openCollaborationSession")}</button></p>
  {/each}
  {#if notice}<p class="notice" role="status">{notice}</p>{/if}
  <div class="detail-grid">
    <div class="main-column">
      <section class="detail-panel"><header><h2>{$t("collaborationBoard.sessions")}</h2><button onclick={()=>showAttach=!showAttach}><Link2 size={15}/>{$t("collaborationBoard.attachSession")}</button></header>{#if showAttach}<form class="attach" onsubmit={(event)=>{event.preventDefault();attach()}}><select required bind:value={attachSelection}><option value="">{$t("collaborationBoard.chooseSession")}</option>{#each sessionCandidates as item}<option value={`${item.kind}:${item.id}`}>{item.title} · {item.provider?providerDisplayName(item.provider):$t("collaborationBoard.collaboration")} · {$t(`task.status.${item.status}`)}</option>{/each}</select><button disabled={busy==="attach"}>{$t("common.add")}</button></form>{/if}<div class="sessions" class:scroll={showAllSessions&&hiddenSessions}>{#each visibleSessions as session}<button type="button" onclick={()=>onopensession(session.kind,session.id)}><span class="session-icon">{session.kind==="task"?"T":"C"}</span><span><strong>{session.title||session.id}</strong><small>{session.provider?providerDisplayName(session.provider):$t("collaborationBoard.collaboration")} · {session.role||$t("collaborationBoard.role.implementer")} · {$t(`task.status.${session.status}`)}</small><small>{session.executionHostId??$t("common.unknown")} · {formatted(session.updatedAt)}</small>{#if session.error}<em>{session.error}</em>{:else if session.result}<em>{session.result}</em>{/if}</span></button>{:else}<p class="board-detail-empty">{$t("collaborationBoard.noSessions")}</p>{/each}</div>{#if hiddenSessions}<button type="button" class="list-more" onclick={()=>showAllSessions=!showAllSessions}>{showAllSessions?$t("collaborationBoard.showLess"):$t("collaborationBoard.showMore",{count:hiddenSessions})}</button>{/if}</section>
      <section class="detail-panel"><header><h2>{$t("collaborationBoard.timeline")}</h2></header>{#if loading}<p class="board-detail-empty">{$t("task.loading")}</p>{:else}{#if hiddenEvents}<button type="button" class="list-more" onclick={()=>showAllEvents=!showAllEvents}>{showAllEvents?$t("collaborationBoard.showLess"):$t("collaborationBoard.showMore",{count:hiddenEvents})}</button>{/if}<ol class="timeline" class:scroll={showAllEvents&&hiddenEvents}>{#each visibleEvents as event}<li><i></i><div><strong>{$t(`collaborationBoard.event.${event.eventType}`)}</strong>{#if payload(event).title}<span>{String(payload(event).title)}</span>{:else if payload(event).summary}<span>{String(payload(event).summary)}</span>{:else if payload(event).error}<span>{String(payload(event).error)}</span>{/if}<small>{formatted(event.createdAt)}</small></div></li>{:else}<li class="board-detail-empty">{$t("collaborationBoard.noEvents")}</li>{/each}</ol>{/if}</section>
    </div>
    <aside class="detail-panel roles"><header><h2>{$t("collaborationBoard.roles")}</h2></header>{#each [["implementer","collaborationBoard.role.implementer"],["reviewer","collaborationBoard.role.reviewer"],["secondaryReviewer","collaborationBoard.role.secondaryReviewer"]] as row}{@const role=card.roles[row[0] as keyof typeof card.roles]}<div><strong>{$t(row[1])}</strong>{#if role}<span>{providerDisplayName(role.provider)}</span><small>{roleSummary(role)}</small>{:else}<span>—</span>{/if}</div>{/each}</aside>
  </div>
</section>

<style>
  .board-detail{width:min(1180px,100%);min-width:0;margin:0 auto;padding:20px clamp(14px,3vw,32px) 100px;overflow-x:clip}.detail-header,.header-actions,.actions,.detail-panel>header,.attach{display:flex;align-items:center;gap:8px}.detail-header{justify-content:space-between}.detail-header button,.actions button,.detail-panel header button,.attach button{display:flex;align-items:center;gap:6px;padding:8px 11px;border:1px solid var(--line);border-radius:9px;background:var(--surface);color:var(--text)}.back{border:0!important;background:transparent!important}.hero{display:flex;justify-content:space-between;gap:20px;margin:24px 0 18px}.kicker{color:var(--accent);font-size:11px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}.hero h1{margin:5px 0 9px;font-size:clamp(25px,4vw,38px)}.hero p{max-width:720px;margin:0;color:var(--muted);line-height:1.55}.hero-state{display:flex;flex-direction:column;align-items:flex-end;gap:7px}.hero-state span,.hero-state small{padding:6px 10px;border-radius:999px;background:var(--surface-2);white-space:nowrap}.hero-state .attention{color:#f59e0b}.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.facts>span{display:flex;min-width:0;overflow-wrap:anywhere;flex-direction:column;gap:5px;padding:12px;border:1px solid var(--line);border-radius:11px;background:var(--panel);font-size:13px}.facts strong{color:var(--muted);font-size:11px}.facts i{display:flex;align-items:center;gap:4px;font-style:normal}.actions{flex-wrap:wrap;margin:14px 0}.actions .complete{margin-left:auto;background:var(--accent);color:var(--on-accent)}.automation-bar{display:flex;min-width:0;align-items:center;gap:10px;flex-wrap:wrap;margin:0 0 14px;padding:12px;border:1px solid var(--line);border-radius:11px;background:var(--panel)}.automation-bar>div{display:flex;min-width:150px;flex:1;flex-direction:column;gap:3px}.automation-bar small,.automation-bar label span,.automation-bar em{color:var(--muted);font-size:11px;font-style:normal}.automation-bar em{display:block;margin-top:3px;color:var(--amber)}.automation-bar label{display:flex;align-items:center;gap:7px}.automation-bar select,.automation-bar button{max-width:100%;padding:8px 10px;border:1px solid var(--line);border-radius:9px;background:var(--surface);color:var(--text)}.automation-bar button{display:flex;align-items:center;gap:6px}.automation-bar .complete{background:var(--accent);color:var(--on-accent)}.notice{padding:10px;border-radius:9px;background:var(--surface-2);font-size:13px}.collaboration-wait{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.collaboration-wait button{padding:6px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--text)}.detail-grid{display:grid;min-width:0;grid-template-columns:minmax(0,1fr) 290px;gap:14px}.main-column{display:grid;min-width:0;gap:14px}.detail-panel{min-width:0;padding:16px;border:1px solid var(--line);border-radius:14px;background:var(--panel)}.detail-panel>header{min-width:0;justify-content:space-between;flex-wrap:wrap;margin-bottom:12px}.detail-panel h2{min-width:0;margin:0;font-size:16px;overflow-wrap:anywhere}.detail-panel header button{min-width:0;max-width:100%}.attach{margin-bottom:12px}.attach select{min-width:0;flex:1;padding:8px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--text)}.sessions{display:grid;min-width:0;gap:8px}.sessions>button{display:grid;min-width:0;grid-template-columns:auto minmax(0,1fr);gap:10px;width:100%;padding:11px;text-align:left;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--text)}.session-icon{display:grid;width:30px;height:30px;place-items:center;border-radius:9px;background:var(--accent-soft);color:var(--accent);font-weight:900}.sessions button>span:last-child{display:flex;min-width:0;flex-direction:column;gap:3px}.sessions small,.sessions em{color:var(--muted);font-size:11px;font-style:normal}.sessions strong,.sessions small,.sessions em{overflow-wrap:anywhere;word-break:break-word}.sessions em{display:-webkit-box;overflow:hidden;white-space:normal;-webkit-line-clamp:3;line-clamp:3;-webkit-box-orient:vertical}.roles>div{display:flex;flex-direction:column;gap:4px;padding:11px 0;border-top:1px solid var(--line)}.roles>div strong,.roles span,.roles small{overflow-wrap:anywhere;word-break:break-word}.roles>div strong,.roles small{color:var(--muted);font-size:11px}.list-more{display:flex;align-items:center;justify-content:center;width:100%;margin-top:10px;padding:8px 11px;border:1px solid var(--line);border-radius:9px;background:var(--surface);color:var(--muted);font-size:12px;font-weight:700}.scroll{max-height:min(52vh,430px);overflow:auto;overscroll-behavior:contain}.sessions.scroll{padding-right:4px}.timeline{margin:0;padding:0;list-style:none}.timeline li{display:grid;grid-template-columns:12px 1fr;gap:9px;padding:6px 0}.timeline li>i{width:8px;height:8px;margin-top:5px;border-radius:50%;background:var(--accent)}.timeline li>div{display:flex;flex-direction:column;gap:3px}.timeline span,.timeline small{color:var(--muted);font-size:12px}.board-detail-empty{color:var(--muted);font-size:13px}@media(max-width:800px){.detail-grid{grid-template-columns:1fr}.roles{order:-1}.facts{grid-template-columns:1fr 1fr}.hero{margin-top:16px}}@media(max-width:520px){.automation-bar{align-items:stretch;flex-direction:column}.automation-bar label{justify-content:space-between}.automation-bar button{justify-content:center}.board-detail{padding-top:12px}.detail-header .header-actions button{font-size:0}.hero{display:block}.hero-state{align-items:flex-start;flex-direction:row;margin-top:14px}.facts{grid-template-columns:1fr}.actions{display:grid;grid-template-columns:1fr 1fr}.actions button{justify-content:center}.actions .complete{margin:0}.attach{align-items:stretch;flex-direction:column}.detail-panel{padding:13px}}
</style>
